"use client";
import React, { useEffect, useState } from "react";
import postSubscribe from "@/services/subscribe";
import PopularDestinations from "../home-page/popular-destinations";
import { getBlogPosts } from "@/services/blog";
import Destinations from "../after-your-booking/destinations";

const featured = [
  {
    title: "5 Places You Have to See in Dubai & Things to do in Dubai in 2025",
    image: "/magazine/dubai.jpg",
    href: "/blog/5-places-you-have-to-see-in-dubai-things-to-do-in-dubai-in-2023",
    excerpt:
      "A curated list of must-visit attractions and activities in Dubai, showcasing the city's dynamic blend of modernity and tradition — from the Burj Khalifa and Palm Jumeirah to desert safaris and luxury yacht tours.",
  },
  {
    title: "Ultimate Guide to visit Pamukkale — Turkey's Cotton Castles",
    image: "/magazine/Pamukkale.jpg",
    href: "/blog/ultimate-guide-to-visit-pamukkale-turkeys-cotton-castles",
    excerpt:
      "A detailed exploration of Pamukkale, one of Turkey's most iconic natural wonders — the best times to visit, how to explore the white mineral terraces, and the nearby ancient city of Hierapolis.",
  },
  {
    title: "Explore The Best 6 Antalya Turkey Tours in 2026",
    image: "/magazine/Antalya.jpg",
    href: "/blog/explore-things-to-do-in-antalya-for-free",
    excerpt:
      "Top-rated tours in Antalya, a stunning Turkish Riviera destination known for its beaches, ancient ruins, and vibrant culture — historical explorations, adventure excursions, and relaxing scenic tours.",
  },
  {
    title: "Facts about Mesopotamia: The Cradle Of Civilization",
    image: "/magazine/Mesopotamian.webp",
    href: "/blog/facts-about-mesopotamia-the-cradle-of-civilization",
    excerpt:
      "The historical significance of Mesopotamia, the birthplace of modern civilization — where the first cities, writing systems, and laws emerged between the Tigris and Euphrates rivers.",
  },
  {
    title:
      "The Beauty and Significance of Eco-Tourism: A Sustainable Travel Experience",
    image: "/magazine/EcoTourism1.avif",
    href: "/blog/explore-the-beauty-and-significance-of-eco-tourism-a-sustainable-travel-experience",
    excerpt:
      "Eco-tourism as a way to enjoy nature responsibly — sustainable travel that supports conservation, protects wildlife, and benefits local communities while minimizing environmental impact.",
  },
  {
    title:
      "Turkey's Accessible Travel Destinations for Disabled Travelers in 2026",
    image: "/magazine/turkey.jpg",
    href: "/blog/turkeys-accessible-travel-destinations-for-disabled-visitors-in-2022",
    excerpt:
      "The best destinations in Turkey offering inclusive and accessible travel — Istanbul, Antalya, and Cappadocia, with accessible accommodations, transportation, and wheelchair-friendly sites.",
  },
  {
    title: "Ecotourism: A Comprehensive Overview",
    image: "/magazine/EcoTourism2.jpg",
    href: "/blog/ecotourism-a-comprehensive-overview",
    excerpt:
      "The concept of eco-friendly travel — tourism that promotes environmental conservation, sustainability, and respect for local cultures, encouraging travelers to make a positive impact on the planet.",
  },
];

const DaysMagazine = () => {
  const [data, setData] = useState([]);
  const [subscribeLoading, setSubscribeLoading] = useState(false);
  const [subscribeMail, setSubscribeMail] = useState("");
  const [subscribeStatus, setSubscribeStatus] = useState("");
  const [subscribeErrorMessage, setSubscribeErrorMessage] = useState("");
  const isEmail = (email: string) =>
    /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i.test(email);

  const subscribePost = async () => {
    if (!subscribeMail || !isEmail(subscribeMail)) {
      setSubscribeErrorMessage("Please specify a valid email address");
      setSubscribeStatus("error");
    } else {
      setSubscribeLoading(true);
      setSubscribeStatus("");
      await postSubscribe(subscribeMail).then(() => {
        setSubscribeMail("");
        setSubscribeStatus("success");
        setSubscribeLoading(false);
      });
    }
  };

  useEffect(() => {
    getBlogPosts({ page: 1, search: "", category: "", author_id: "" }).then(
      (res) => {
        setData(res.data);
      },
    );
  }, []);

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Featured hero */}
      <section className="tw-relative tw-overflow-hidden">
        <img
          src={featured[0].image}
          alt={featured[0].title}
          className="tw-h-[clamp(420px,60vh,620px)] tw-w-full tw-object-cover"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.35) 0%, rgba(20,16,28,0.55) 55%, rgba(20,16,28,0.85) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-absolute tw-inset-0 tw-flex tw-items-end">
          <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-pb-12 md:tw-pb-16">
            <div className="tw-max-w-[760px]">
              <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
                Days Magazine
              </span>
              <h1 className="tw-mt-4 tw-text-[clamp(28px,4vw,46px)] tw-font-bold tw-tracking-tight tw-leading-[1.1] tw-text-white tw-m-0">
                {featured[0].title}
              </h1>
              <p className="tw-mt-4 tw-mb-0 tw-text-[16px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
                {featured[0].excerpt}
              </p>
              <a
                href={featured[0].href}
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-white hover:tw-bg-[#f3f1f7] tw-text-[#854ec9] tw-font-semibold tw-text-[14px] tw-px-6 tw-py-3 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Read more <span aria-hidden="true">→</span>
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* Featured grid */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {featured.slice(1).map((article) => (
              <a
                key={article.href}
                href={article.href}
                target="_blank"
                rel="noopener noreferrer"
                className="tw-group tw-relative tw-flex tw-min-h-[360px] tw-overflow-hidden tw-rounded-2xl tw-no-underline"
              >
                <img
                  src={article.image}
                  alt={article.title}
                  loading="lazy"
                  className="tw-absolute tw-inset-0 tw-h-full tw-w-full tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-105"
                />
                <div
                  className="tw-absolute tw-inset-0"
                  style={{
                    background:
                      "linear-gradient(180deg, rgba(20,16,28,0.1) 0%, rgba(20,16,28,0.55) 55%, rgba(20,16,28,0.9) 100%)",
                  }}
                  aria-hidden="true"
                />
                <div className="tw-relative tw-mt-auto tw-p-6">
                  <h2 className="tw-text-[19px] tw-font-bold tw-leading-snug tw-text-white tw-m-0">
                    {article.title}
                  </h2>
                  <p className="tw-mt-2 tw-mb-0 tw-text-[13px] tw-leading-[1.6] tw-text-white/80 tw-line-clamp-3">
                    {article.excerpt}
                  </p>
                  <span className="tw-mt-4 tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-border tw-border-solid tw-border-white/40 tw-px-4 tw-py-1.5 tw-text-[12px] tw-font-semibold tw-uppercase tw-tracking-wide tw-text-white group-hover:tw-bg-white group-hover:tw-text-[#14101c] tw-transition-colors">
                    Read more
                  </span>
                </div>
              </a>
            ))}
          </div>
        </div>
      </section>

      {/* Recent articles */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0 tw-mb-8 tw-pb-4 tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
            Recent Articles
          </h2>
          <div className="tw-grid tw-grid-cols-2 lg:tw-grid-cols-4 tw-gap-4 lg:tw-gap-5">
            {data.map((item: any) => (
              <a
                key={item.id}
                href={"/blog/" + item.slug}
                target="_blank"
                rel="noopener noreferrer"
                title={item.title}
                className="tw-group tw-relative tw-flex tw-min-h-[240px] tw-overflow-hidden tw-rounded-2xl tw-no-underline"
              >
                <img
                  src={item.main_image}
                  alt={item.title}
                  loading="lazy"
                  className="tw-absolute tw-inset-0 tw-h-full tw-w-full tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-105"
                />
                <div
                  className="tw-absolute tw-inset-0"
                  style={{
                    background:
                      "linear-gradient(180deg, rgba(20,16,28,0.15) 0%, rgba(20,16,28,0.7) 100%)",
                  }}
                  aria-hidden="true"
                />
                <h3
                  className="tw-relative tw-mt-auto tw-p-4 tw-text-[15px] tw-font-bold tw-leading-snug tw-text-white tw-m-0"
                  dangerouslySetInnerHTML={{ __html: item.title }}
                />
              </a>
            ))}
          </div>
          <div className="tw-mt-10 tw-text-center">
            <a
              href="/blog"
              target="_blank"
              rel="noopener noreferrer"
              className="tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-7 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
            >
              All Blogs <span aria-hidden="true">→</span>
            </a>
          </div>
        </div>
      </section>

      <PopularDestinations />

      {/* Newsletter */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-relative tw-overflow-hidden tw-rounded-3xl tw-px-7 tw-py-12 md:tw-px-12 md:tw-py-14">
            <div
              className="tw-absolute tw-inset-0"
              style={{
                background:
                  "linear-gradient(120deg, #854ec9 0%, #6a3da4 60%, #4f2d7f 100%)",
              }}
              aria-hidden="true"
            />
            <div className="tw-relative tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-8 tw-items-center">
              <div>
                <h2 className="tw-text-[clamp(22px,3vw,30px)] tw-font-bold tw-tracking-tight tw-text-white tw-m-0">
                  Subscribe to Our Newsletter
                </h2>
                <p className="tw-mt-3 tw-mb-0 tw-text-[15px] tw-leading-[1.6] tw-text-white/85">
                  Enjoy savings of up to 50% on our tours! Gain exclusive access
                  to email-only offers for members.
                </p>
              </div>
              <div>
                {subscribeStatus === "error" && (
                  <div className="tw-mb-3 tw-rounded-xl tw-bg-white/15 tw-border tw-border-solid tw-border-white/30 tw-px-4 tw-py-3 tw-text-[14px] tw-font-medium tw-text-white">
                    {subscribeErrorMessage}
                  </div>
                )}
                {subscribeStatus === "success" && (
                  <div className="tw-mb-3 tw-rounded-xl tw-bg-white/15 tw-border tw-border-solid tw-border-white/30 tw-px-4 tw-py-3 tw-text-[14px] tw-font-medium tw-text-white">
                    Your registration has been received. We thank you.
                  </div>
                )}
                <div className="tw-flex tw-flex-col sm:tw-flex-row tw-gap-2.5">
                  <input
                    type="email"
                    id="magazine-subscribe-mail-input"
                    placeholder="Your email"
                    aria-label="Your email"
                    value={subscribeMail}
                    onChange={(e) => setSubscribeMail(e.target.value)}
                    className="tw-flex-1 tw-rounded-full tw-border tw-border-solid tw-border-white/30 tw-bg-white/95 tw-px-5 tw-py-3 tw-text-[15px] tw-text-[#14101c] tw-outline-none focus:tw-ring-2 focus:tw-ring-white/60"
                  />
                  <button
                    type="button"
                    disabled={subscribeLoading}
                    onClick={subscribePost}
                    className="tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-bg-white hover:tw-bg-[#f3f1f7] disabled:tw-opacity-70 tw-text-[#854ec9] tw-font-semibold tw-text-[15px] tw-px-7 tw-py-3 tw-rounded-full tw-transition-colors"
                  >
                    {subscribeLoading ? "Loading..." : "Subscribe"}
                  </button>
                </div>
                <p className="tw-mt-3 tw-mb-0 tw-text-[12px] tw-leading-[1.5] tw-text-white/75">
                  By submitting this form, I agree to the TravelShop Booking{" "}
                  <a
                    href="/terms-of-use"
                    className="tw-font-semibold tw-text-white"
                  >
                    Terms of Use
                  </a>{" "}
                  and{" "}
                  <a
                    href="/privacy-policy"
                    className="tw-font-semibold tw-text-white"
                  >
                    Privacy Policy
                  </a>
                  .
                </p>
              </div>
            </div>
          </div>
        </div>
      </section>

      <Destinations />
    </main>
  );
};

export default DaysMagazine;
